// Spectra3D Script - compiler driver (spsc)
//
//   spsc source.sps              compile, write out/source.spc and run it
//   spsc source.sps -o app.spc   compile only
//   spsc source.sps --check      syntax check only
//   spsc source.sps --dump       print the generated bytecode
#include "internal/compiler.h"
#include "internal/parser.h"
#include "internal/program.h"
#include "internal/spslib.h"
#include "internal/term.h"
#include "internal/vm.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// the version of the language (src/api/api_version.c)
const char* sps_version(void);

static bool file_exists(const char* path) {
    FILE* file = fopen(path, "rb");
    if (!file) return false;
    fclose(file);
    return true;
}

static char* read_file(const char* path) {
    FILE* file = fopen(path, "rb");
    if (!file) {
        term_color(stderr, TERM_BRED);
        fprintf(stderr, "sps: cannot open '%s'", path);
        term_reset(stderr);
        fprintf(stderr, "\n");
        return NULL;
    }
    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    fseek(file, 0, SEEK_SET);
    if (size < 0) size = 0;
    char* buffer = (char*)malloc((size_t)size + 1);
    if (!buffer) {
        fclose(file);
        fprintf(stderr, "sps: out of memory\n");
        return NULL;
    }
    if (size > 0 && fread(buffer, 1, (size_t)size, file) != (size_t)size) {
        free(buffer);
        fclose(file);
        fprintf(stderr, "sps: cannot read '%s'\n", path);
        return NULL;
    }
    buffer[size] = '\0';
    fclose(file);
    return buffer;
}

static void dump_proto(Program* program, int index) {
    FunctionProto* proto = program->protos[index];
    printf("--- function '%s' (arity=%d locals=%d upvalues=%d) ---\n",
           proto->name ? proto->name : "?", proto->arity, proto->stack_size, proto->upvalue_count);
    for (int i = 0; i < proto->code_len; i++) {
        Instr* instr = &proto->code[i];
        printf("  %4d  %-16s", i, OP_NAMES[instr->op]);
        switch (instr->op) {
            case OP_CONST:
            case OP_GET_LOCAL:
            case OP_SET_LOCAL:
            case OP_GET_GLOBAL:
            case OP_SET_GLOBAL:
            case OP_GET_UPVAL:
            case OP_SET_UPVAL:
            case OP_NATIVE:
            case OP_JMP:
            case OP_JMP_IF_FALSE:
            case OP_JMP_IF_TRUE:
            case OP_CLOSURE:
            case OP_CLOSE_UPVAL:
                printf(" %d", instr->c);
                break;
            case OP_CALL:
            case OP_LIST:
                printf(" %d", instr->a);
                break;
            default:
                break;
        }
        printf("   ; line %d\n", instr->line);
    }
}

static void dump_program(Program* program) {
    printf("Spectra3D Script bytecode dump\n");
    printf("globals: %d (builtins: %d)\n", program->global_count, program->builtin_count);
    for (int i = 0; i < program->proto_count; i++) {
        dump_proto(program, i);
    }
}

static void make_output_path(const char* source, char* buffer, size_t size) {
    const char* slash = strrchr(source, '/');
    const char* backslash = strrchr(source, '\\');
    const char* base = source;
    if (slash) base = slash + 1;
    if (backslash && backslash + 1 > base) base = backslash + 1;

    const char* dot = strrchr(base, '.');
    size_t length = dot ? (size_t)(dot - base) : strlen(base);
    snprintf(buffer, size, "out/%.*s.spc", (int)length, base);
}

// The interactive mode: every line is added to the session and the whole
// session is executed again, so the functions stay defined.
static int run_repl(void) {
    printf("Spectra3D Script %s - the interactive mode, 'exit' to quit\n", sps_version());
    char line[2048];
    char* session = NULL;
    size_t length = 0;

    for (;;) {
        printf("> ");
        fflush(stdout);
        if (!fgets(line, sizeof(line), stdin)) break;

        size_t added = strlen(line);
        session = (char*)realloc(session, length + added + 1);
        if (!session) {
            fprintf(stderr, "sps: out of memory\n");
            return 1;
        }
        memcpy(session + length, line, added + 1);
        length += added;

        if (strstr(session, "exit") != NULL) break;

        Program program;
        program_init(&program);
        VM* vm = vm_new(&program);

        Parser parser;
        memset(&parser, 0, sizeof(parser));
        snprintf(parser.file, sizeof(parser.file), "<repl>");
        Node* ast = parser_parse(&parser, &program.arena, session);
        if (ast && compiler_compile(&program, vm, ast, "<repl>")) {
            vm_init_globals(vm);
            vm_run(vm);
        } else if (!ast) {
            fprintf(stderr, "sps: the syntax error, the line is ignored\n");
        }
        vm_free(vm);
        program_release(&program);
    }

    free(session);
    return 0;
}

// The project file: the name, the main script and the folders of the
// packages.
typedef struct {
    char  name[128];
    char  main_script[256];
    char* lib_paths[8];
    int   lib_count;
    bool  loaded;
} Project;

static Project g_project;

static bool read_project(const char* path) {
    FILE* file = fopen(path, "rb");
    if (!file) return false;

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    fseek(file, 0, SEEK_SET);
    if (size < 0) size = 0;
    char* text = (char*)malloc((size_t)size + 1);
    if (!text) {
        fclose(file);
        return false;
    }
    size_t read = fread(text, 1, (size_t)size, file);
    fclose(file);
    text[read] = '\0';

    Program program;
    program_init(&program);
    VM* vm = vm_new(&program);

    bool ok = false;
    Value document = sps_json_parse_text(vm, text, strlen(text), &ok);
    if (ok && document.type == VAL_DICT) {
        ObjDict* dict = (ObjDict*)document.as.obj;
        for (uint32_t i = 0; i < dict->capacity; i++) {
            if (dict->entries[i].state != 1) continue;
            if (dict->entries[i].key.type != VAL_STRING) continue;
            const char* key = ((ObjString*)dict->entries[i].key.as.obj)->chars;
            Value item = dict->entries[i].value;

            if (strcmp(key, "name") == 0 && item.type == VAL_STRING) {
                snprintf(g_project.name, sizeof(g_project.name), "%s",
                         ((ObjString*)item.as.obj)->chars);
            } else if (strcmp(key, "main") == 0 && item.type == VAL_STRING) {
                snprintf(g_project.main_script, sizeof(g_project.main_script), "%s",
                         ((ObjString*)item.as.obj)->chars);
            } else if (strcmp(key, "lib") == 0 && item.type == VAL_LIST) {
                ObjList* list = (ObjList*)item.as.obj;
                for (uint32_t j = 0; j < list->count && g_project.lib_count < 8; j++) {
                    if (list->items[j].type != VAL_STRING) continue;
                    g_project.lib_paths[g_project.lib_count] =
                        strdup(((ObjString*)list->items[j].as.obj)->chars);
                    g_project.lib_count++;
                }
            }
        }
        ok = true;
    }

    vm_free(vm);
    program_release(&program);
    g_project.loaded = ok;
    return ok;
}

static void usage(void) {
    printf("Spectra3D Script compiler (spsc)\n");
    printf("usage: spsc <source.sps> [options]\n");
    printf("  -o <file>    write the bytecode to <file>\n");
    printf("  --run        run the compiled program\n");
    printf("  --check      only check the syntax\n");
    printf("  --dump       print the generated bytecode\n");
    printf("  --stats      print memory statistics\n");
    printf("  --time       print the elapsed time\n");
}

int main(int argc, char** argv) {
    term_init();
    const char* source_path = NULL;
    const char* output_path = NULL;
    bool run = false;
    bool check_only = false;
    bool dump = false;
    bool show_time = false;
    bool show_stats = false;
    bool repl = false;
    const char* project_path = NULL;

    for (int i = 1; i < argc; i++) {
        const char* arg = argv[i];
        if (strcmp(arg, "-o") == 0 && i + 1 < argc) {
            output_path = argv[++i];
        } else if (strcmp(arg, "--run") == 0) {
            run = true;
        } else if (strcmp(arg, "--check") == 0) {
            check_only = true;
        } else if (strcmp(arg, "--dump") == 0) {
            dump = true;
        } else if (strcmp(arg, "--time") == 0) {
            show_time = true;
        } else if (strcmp(arg, "--project") == 0 && i + 1 < argc) {
            project_path = argv[++i];
        } else if (strcmp(arg, "--repl") == 0) {
            repl = true;
        } else if (strcmp(arg, "--stats") == 0) {
            show_stats = true;
        } else if (strcmp(arg, "-h") == 0 || strcmp(arg, "--help") == 0) {
            usage();
            return 0;
        } else if (arg[0] == '-') {
            term_color(stderr, TERM_BRED);
            fprintf(stderr, "sps: unknown option '%s'", arg);
            term_reset(stderr);
            fprintf(stderr, "\n");
            return 1;
        } else {
            source_path = arg;
        }
    }

    if (repl) {
        return run_repl();
    }

    // the project file: the main script and the folders of the packages
    if (!project_path) {
        if (file_exists("spsproject.json")) project_path = "spsproject.json";
    }
    if (project_path && read_project(project_path)) {
        if (g_project.lib_count > 0) {
            compiler_set_search_paths((const char* const*)g_project.lib_paths, g_project.lib_count);
        }
        if (!source_path && g_project.main_script[0]) source_path = g_project.main_script;
    }

    if (!source_path) {
        usage();
        return 1;
    }

    // without an explicit output file the program is compiled and executed
    if (!output_path && !check_only) run = true;

    char* source = read_file(source_path);
    if (!source) return 1;

    clock_t started = clock();

    Program program;
    program_init(&program);

    VM* vm = vm_new(&program);
    vm->script_name = source_path;

    Parser parser;
    memset(&parser, 0, sizeof(parser));
    snprintf(parser.file, sizeof(parser.file), "%s", source_path);
    Node* ast = parser_parse(&parser, &program.arena, source);
    free(source);

    int status = 0;
    if (!ast) {
        status = 1;
    } else if (!compiler_compile(&program, vm, ast, source_path)) {
        status = 1;
    } else {
        vm_init_globals(vm);

        if (dump) dump_program(&program);

        if (!check_only) {
            char default_path[512];
            if (!output_path) {
                make_output_path(source_path, default_path, sizeof(default_path));
                output_path = default_path;
            }
            if (!program_serialize(&program, output_path)) {
                status = 1;
            }
        }

        if (run && status == 0) {
            vm_run(vm);
        }
    }

    if (show_stats) vm_print_stats(vm);

    if (show_time) {
        double seconds = (double)(clock() - started) / (double)CLOCKS_PER_SEC;
        fprintf(stderr, "[sps] %.3f s\n", seconds);
    }

    vm_free(vm);
    program_release(&program);
    return status;
}
